-- #269: the "Ourco Editorial" template gets the real brand logos (white primary logo
-- at 180px in a warm-ink #15130e header, no wordmark beside it; the logomark in the hero
-- chip). Only rewrites a row whose blocks are still exactly the 0072 seed, so it is a
-- no-op on prod (already updated by hand) and on any row someone has edited.
-- The new JSON is src/lib/editorial-template.ts editorialTemplateBlocks(), sanitised; a
-- test keeps the two identical.
UPDATE templates SET blocks = '[{"id":"ed-header","type":"section","bg":"#15130e","padding":"sm","width":"full","blocks":[{"id":"ed-logo","type":"image","src":"https://crm.myapp.example/img/logo-white.png","alt":"Ourco","href":"https://ourco.example","width":180}],"color":"#ffffff","align":"center"},{"id":"ed-hero","type":"section","bg":"#1a9ec4","padding":"lg","width":"full","blocks":[{"id":"ed-chip","type":"image","src":"https://crm.myapp.example/img/logomark.png","alt":"Ourco","width":48,"style":"chip"},{"id":"ed-eyebrow","type":"eyebrow","content":[{"type":"text","text":"Campaign label"}]},{"id":"ed-headline","type":"heading","level":1,"text":"Your big, bold headline goes here.","content":[{"type":"text","text":"Your big, bold headline goes here."}],"size":"display"},{"id":"ed-intro","type":"paragraph","content":[{"type":"text","text":"Intro paragraph: one or two sentences on why this email matters and what the reader should do next."}]},{"id":"ed-milestones","type":"milestones","items":[{"title":[{"type":"text","text":"Step 1"}],"label":[{"type":"text","text":"Label"}]},{"title":[{"type":"text","text":"Step 2"}],"label":[{"type":"text","text":"Label"}]},{"title":[{"type":"text","text":"Step 3"}],"label":[{"type":"text","text":"Label"}]},{"title":[{"type":"text","text":"Step 4"}],"label":[{"type":"text","text":"Label"}]}],"rule":true},{"id":"ed-cta","type":"button","label":"Book a call","href":"https://ourco.example/book/","align":"left","linkLabel":"ourco.example/book/","linkHref":"https://ourco.example/book/"}],"color":"#000000"},{"id":"ed-body","type":"section","bg":"#ffffff","padding":"lg","width":"full","blocks":[{"id":"ed-content","type":"content"},{"id":"ed-steps","type":"list","ordered":true,"items":[[{"type":"text","text":"First step: what happens first, in a sentence."}],[{"type":"text","text":"Second step: what the reader can expect next."}],[{"type":"text","text":"Third step: the outcome. Delete this list if you do not need it."}]],"style":"steps"}],"color":"#333333"}]', updated_at = CURRENT_TIMESTAMP
WHERE name = 'Ourco Editorial'
  AND blocks = '[{"id":"ed-header","type":"section","bg":"#191919","padding":"sm","width":"full","blocks":[{"id":"ed-logo","type":"image","src":"https://crm.myapp.example/icons/icon-512.png","alt":"Ourco","href":"https://ourco.example","width":40,"beside":"Ourco"}],"color":"#ffffff","align":"center"},{"id":"ed-hero","type":"section","bg":"#1a9ec4","padding":"lg","width":"full","blocks":[{"id":"ed-chip","type":"image","src":"https://crm.myapp.example/icons/icon-512.png","alt":"Ourco","width":48,"style":"chip"},{"id":"ed-eyebrow","type":"eyebrow","content":[{"type":"text","text":"Campaign label"}]},{"id":"ed-headline","type":"heading","level":1,"text":"Your big, bold headline goes here.","content":[{"type":"text","text":"Your big, bold headline goes here."}],"size":"display"},{"id":"ed-intro","type":"paragraph","content":[{"type":"text","text":"Intro paragraph: one or two sentences on why this email matters and what the reader should do next."}]},{"id":"ed-milestones","type":"milestones","items":[{"title":[{"type":"text","text":"Step 1"}],"label":[{"type":"text","text":"Label"}]},{"title":[{"type":"text","text":"Step 2"}],"label":[{"type":"text","text":"Label"}]},{"title":[{"type":"text","text":"Step 3"}],"label":[{"type":"text","text":"Label"}]},{"title":[{"type":"text","text":"Step 4"}],"label":[{"type":"text","text":"Label"}]}],"rule":true},{"id":"ed-cta","type":"button","label":"Book a call","href":"https://ourco.example/book/","align":"left","linkLabel":"ourco.example/book/","linkHref":"https://ourco.example/book/"}],"color":"#000000"},{"id":"ed-body","type":"section","bg":"#ffffff","padding":"lg","width":"full","blocks":[{"id":"ed-content","type":"content"},{"id":"ed-steps","type":"list","ordered":true,"items":[[{"type":"text","text":"First step: what happens first, in a sentence."}],[{"type":"text","text":"Second step: what the reader can expect next."}],[{"type":"text","text":"Third step: the outcome. Delete this list if you do not need it."}]],"style":"steps"}],"color":"#333333"}]';
